99	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
100	     *  separated by '@', none of which contain whitespace or a second '@'. */
101	    private static final java.util.regex.Pattern EMAIL_PATTERN =
102	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
103	
104	    /**
105	     * Normalize the optional email: absent stays absent; when present it must be syntactically
106	     * valid and is lower-cased. Returns {@code false} if present but invalid.
107	     */
108	    private boolean normalizeEmail(Owner owner) {
109	        String email = owner.getEmail();
110	        if (email == null || email.isEmpty()) {
111	            owner.setEmail(null);
112	            return true;
113	        }
114	        if (!EMAIL_PATTERN.matcher(email).matches()) {
115	            return false;
116	        }
117	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
118	        return true;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        HttpHeaders headers = new HttpHeaders();
125	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
126	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().replaceAll("\\D", "");
127	        if (telephone.length() != 10) {
128	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	        }
130	        if (!normalizeEmail(owner)) {
131	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	        }
133	        for (Owner existing : this.clinicService.findAllOwners()) {
134	            String existingTelephone = existing.getTelephone() == null ? ""
135	                : existing.getTelephone().replaceAll("\\D", "");
136	            if (telephone.equals(existingTelephone)) {
137	                return new ResponseEntity<>(HttpStatus.CONFLICT);
138	            }
139	        }
140	        owner.setTelephone(telephone);
141	        this.clinicService.saveOwner(owner);
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
160	        currentOwner.setEmail(ownerFieldsDto.getEmail());
161	        if (!normalizeEmail(currentOwner)) {
162	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
163	        }
164	        this.clinicService.saveOwner(currentOwner);
165	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Transactional
170	    @Override
171	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        this.clinicService.deleteOwner(owner);
177	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
